<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
$role=$_SESSION['role']??'';$uid=(int)($_SESSION['user_id']??0);$isReviewer=in_array($role,['system_admin','sub_admin'],true);
if(!$isReviewer&&$role!=='admin'){http_response_code(403);exit('Your role cannot view school edit requests.');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Choose a school.');}$db=db();$q=$db->prepare('SELECT id,name,location FROM schools WHERE id=?'.($role==='admin'?' AND EXISTS(SELECT 1 FROM school_memberships WHERE school_id=schools.id AND user_id=?)':''));$q->execute($role==='admin'?[$id,$uid]:[$id]);$school=$q->fetch();if(!$school){http_response_code(404);exit('School not found in your access.');}
if($isReviewer){$q=$db->prepare("SELECT u.id,u.name,u.email,p.active edit_allowed FROM school_memberships m JOIN users u ON u.id=m.user_id LEFT JOIN school_edit_permissions p ON p.school_id=m.school_id AND p.user_id=u.id WHERE m.school_id=? AND u.role='admin' AND u.status='active' ORDER BY u.name");$q->execute([$id]);$appointedAdmins=$q->fetchAll();$q=$db->prepare('SELECT r.*,u.name requested_by_name,reviewer.name reviewer_name FROM school_edit_requests r JOIN users u ON u.id=r.requested_by LEFT JOIN users reviewer ON reviewer.id=r.reviewed_by WHERE r.school_id=? ORDER BY (r.status=\'pending\') DESC,r.created_at DESC LIMIT 50');$q->execute([$id]);$requests=$q->fetchAll();}
else{$q=$db->prepare('SELECT active FROM school_edit_permissions WHERE school_id=? AND user_id=?');$q->execute([$id,$uid]);$permission=(bool)$q->fetchColumn();$q=$db->prepare('SELECT r.*,u.name requested_by_name,reviewer.name reviewer_name FROM school_edit_requests r JOIN users u ON u.id=r.requested_by LEFT JOIN users reviewer ON reviewer.id=r.reviewed_by WHERE r.school_id=? AND r.requested_by=? ORDER BY r.created_at DESC LIMIT 20');$q->execute([$id,$uid]);$requests=$q->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>School edit access · <?=e($school['name'])?></title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item active" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item" href="team.php">♧ &nbsp;People</a><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)):?><a class="nav-item" href="requests.php">✉ &nbsp;Requests<?php $requestBadgeCount=pending_school_edit_request_count();if($requestBadgeCount):?><span class="side-nav-count"><?=$requestBadgeCount>99?'99+':$requestBadgeCount?></span><?php endif;?></a><?php endif;?><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin','director'],true)):?><a class="nav-item" href="subscriptions.php">◷ &nbsp;Subscriptions</a><?php endif;?></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><div class="crumb">Workspace <span>/</span><a href="schools.php">Schools</a><span>/</span><a href="school_view.php?id=<?=$id?>"><?=e($school['name'])?></a><span>/</span>Edit access</div><?php if(in_array($_SESSION['role']??'', ['system_admin','sub_admin'],true)):$pendingEditCount=pending_school_edit_request_count();?><a class="notification-bell" href="requests.php#requested" aria-label="<?=$pendingEditCount?> pending edit requests" title="<?=$pendingEditCount?> pending edit requests"><span aria-hidden="true">🔔</span><?php if($pendingEditCount):?><span class="notification-badge"><?=$pendingEditCount>99?'99+':$pendingEditCount?></span><?php endif;?></a><?php endif;?><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name']??'')?></div></div></header><div class="page-content"><section class="setup-hero"><div><div class="eyebrow">SCHOOL EDIT CONTROL</div><h1><?=e($school['name'])?></h1><p class="muted">Manage admin edit access and review proposed detail changes.</p></div><a class="button" href="school_view.php?id=<?=$id?>">Back to school</a></section><?php if(isset($_GET['permission_updated'])):?><div class="notice success" role="status">Edit permission updated.</div><?php endif;?><?php if(isset($_GET['request_sent'])):?><div class="notice success" role="status">Your change request was sent for review.</div><?php endif;?><?php if(isset($_GET['review_updated'])):?><div class="notice success" role="status">The edit request was updated.</div><?php endif;?><?php if($isReviewer):?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">EDIT ACCESS</div><h2>Appointed admins</h2></div></div><?php if($appointedAdmins):?><div class="table-wrap"><table><thead><tr><th>Admin</th><th>Edit permission</th><th>Action</th></tr></thead><tbody><?php foreach($appointedAdmins as $admin):?><tr><td><?=e($admin['name'])?><small><?=e($admin['email']?:'')?></small></td><td><?=$admin['edit_allowed']?'Granted':'Not granted'?></td><td><form method="post" action="school_view.php?id=<?=$id?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=$admin['id']?>"><input type="hidden" name="action" value="<?=$admin['edit_allowed']?'revoke_edit_permission':'grant_edit_permission'?>"><button class="button <?=$admin['edit_allowed']?'danger':'primary'?>" type="submit"><?=$admin['edit_allowed']?'Revoke':'Grant edit access'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No appointed admins</h3><p>Only active admins linked to this school can be granted edit access.</p></div><?php endif;?></section><?php elseif($permission):?><div class="notice success" role="status">You currently have edit permission for this school.</div><?php else:?><div class="notice">You can submit proposed school detail changes for review. A system administrator or sub-system administrator must approve them.</div><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">CHANGE REQUESTS</div><h2><?=$isReviewer?'School edit requests':'Your edit requests'?></h2></div><span class="count-pill"><?=count($requests)?> requests</span></div><?php if($requests):?><div class="table-wrap"><table><thead><tr><?php if($isReviewer):?><th>Requested by</th><?php endif;?><th>Proposed details</th><th>Status</th><th>Requested</th><?php if($isReviewer):?><th>Review</th><?php endif;?></tr></thead><tbody><?php foreach($requests as $request):?><tr><?php if($isReviewer):?><td><?=e($request['requested_by_name'])?></td><?php endif;?><td><strong><?=e($request['proposed_name'])?></strong><small><?=e($request['proposed_location']?:'No location')?> · <?=e($request['proposed_phone']?:'No phone')?></small><details><summary>Original details</summary><small><?=e($request['original_name'])?> · <?=e($request['original_location']?:'No location')?> · <?=e($request['original_phone']?:'No phone')?></small></details></td><td><?=e(ucfirst($request['status']))?><?php if($request['reviewer_name']):?><small> by <?=e($request['reviewer_name'])?></small><?php endif;?></td><td><?=e(date('j M Y H:i',strtotime($request['created_at'])))?></td><?php if($isReviewer):?><td><div class="academic-row-actions"><?php if($request['status']==='pending'):?><form method="post" action="school_view.php?id=<?=$id?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="request_id" value="<?=$request['id']?>"><input type="hidden" name="action" value="approve_school_edit"><button class="button primary" type="submit">Allow</button></form><form method="post" action="school_view.php?id=<?=$id?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="request_id" value="<?=$request['id']?>"><input type="hidden" name="action" value="deny_school_edit"><button class="button" type="submit">Deny</button></form><?php elseif($request['status']==='approved'):?><form method="post" action="school_view.php?id=<?=$id?>" onsubmit="return confirm('Revert this school to the details saved before the approved edit?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="request_id" value="<?=$request['id']?>"><input type="hidden" name="action" value="revert_school_edit"><button class="button danger" type="submit">Revert original</button></form><?php endif;?></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No edit requests</h3><p>Proposed school detail changes will appear here for review.</p></div><?php endif;?></section></div></main></div></body></html>
